{
  "name": "Andor科学相机",
  "name_en": "Andor scientific camera",
  "manufacturer": "Andor",
  "description": "Andor科学相机是一类实验室成像设备，用于采集低噪声、高灵敏度的二维图像数据，常见于显微成像、光谱检测和一般科研实验中的图像记录与数据采集。",
  "description_en": "An Andor scientific camera is a laboratory imaging device used to acquire low-noise, high-sensitivity 2D image data. It is commonly used for microscopy, spectroscopy detection, and general scientific image acquisition in research experiments.",
  "tag_hints": [
    "scientific camera",
    "low-light imaging",
    "microscopy imaging",
    "spectroscopy detection",
    "image acquisition",
    "buffered frame capture"
  ],
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化相机控制库。",
      "description_en": "Initialize the camera control library."
    },
    {
      "action_name": "auto-finalize",
      "description": "结束并释放相机控制库。",
      "description_en": "Finalize and release the camera control library."
    },
    {
      "action_name": "auto-is_implemented",
      "description": "检查指定相机命令或功能是否已实现。",
      "description_en": "Check whether a specified camera command or feature is implemented."
    },
    {
      "action_name": "auto-is_writable",
      "description": "检查指定相机属性或功能是否可写。",
      "description_en": "Check whether a specified camera property or feature is writable."
    },
    {
      "action_name": "auto-queuebuffer",
      "description": "将缓冲区加入采集队列，用于接收后续图像帧。",
      "description_en": "Queue a buffer for acquisition so it can receive upcoming image frames."
    },
    {
      "action_name": "auto-waitbuffer",
      "description": "等待下一帧图像对应的缓冲区就绪。",
      "description_en": "Wait for the next image buffer to become ready."
    },
    {
      "action_name": "auto-command",
      "description": "执行指定的相机命令。",
      "description_en": "Execute a specified camera command."
    },
    {
      "action_name": "auto-getint",
      "description": "获取整数类型的相机属性值。",
      "description_en": "Get an integer-valued camera property."
    },
    {
      "action_name": "auto-setint",
      "description": "设置整数类型的相机属性值。",
      "description_en": "Set an integer-valued camera property."
    },
    {
      "action_name": "auto-getfloat",
      "description": "获取浮点类型的相机属性值。",
      "description_en": "Get a floating-point camera property."
    },
    {
      "action_name": "auto-setfloat",
      "description": "设置浮点类型的相机属性值。",
      "description_en": "Set a floating-point camera property."
    },
    {
      "action_name": "auto-getbool",
      "description": "获取布尔类型的相机属性值。",
      "description_en": "Get a boolean camera property."
    },
    {
      "action_name": "auto-setbool",
      "description": "设置布尔类型的相机属性值。",
      "description_en": "Set a boolean camera property."
    },
    {
      "action_name": "auto-getenumerated",
      "description": "获取枚举类型的相机属性值。",
      "description_en": "Get an enumerated camera property."
    },
    {
      "action_name": "auto-setenumerated",
      "description": "设置枚举类型的相机属性值。",
      "description_en": "Set an enumerated camera property."
    },
    {
      "action_name": "auto-setenumstring",
      "description": "通过字符串选项设置枚举类型的相机属性。",
      "description_en": "Set an enumerated camera property using a string option."
    },
    {
      "action_name": "auto-flush",
      "description": "清空相机采集缓冲队列。",
      "description_en": "Flush the camera acquisition buffer queue."
    }
  ]
}

